const { flight, override, rc, gvar, waypoint, pid, helpers, events } = inav;

if (flight.homeDistance > 100) {
  override.vtx.power = 3; // High power
}

if (flight.homeDistance > 500) {
  override.vtx.power = 4; // Max power
}`},"battery-protection":{name:"Battery Protection",description:"Reduce throttle when battery voltage is low",category:"Safety",code:`// Battery protection - reduce throttle on low voltage
const { flight, override, rc, gvar, waypoint, pid, helpers, events } = inav;

if (flight.cellVoltage < 350) {
  override.throttleScale = 50; // 50% throttle limit
}

if (flight.cellVoltage < 330) {
  override.throttleScale = 25; // 25% throttle limit - RTH!
}`},"rssi-vtx":{name:"RSSI-based VTX Power",description:"Boost VTX power when RSSI drops",category:"VTX",code:`// Boost VTX power when signal weakens
const { flight, override, rc, gvar, waypoint, pid, helpers, events } = inav;

if (flight.rssi < 50) {
  override.vtx.power = 3;
}

if (flight.rssi < 30) {
  override.vtx.power = 4; // Max power
}`},"altitude-stages":{name:"Altitude-based Stages",description:"Different settings at different altitudes",category:"Navigation",code:`// Different VTX settings by altitude
const { flight, override } = inav;

if (flight.altitude > 50) {
  override.vtx.power = 3;
}

if (flight.altitude > 100) {
  override.vtx.power = 4;
}

if (flight.altitude < 10) {
  override.vtx.power = 1; // Low power near ground
}`},"heading-tracking":{name:"Track Heading Changes",description:"Initialize heading on arm, then monitor changes",category:"Navigation",code:`// Track heading changes
const { flight, gvar, edge } = inav;

// Save initial heading once on arm
edge(() => flight.armTimer > 1000, { duration: 0 }, () => {
  gvar[0] = flight.yaw;
});

// If heading changed more than 90 degrees
if (Math.abs(flight.yaw - gvar[0]) > 90) {
  gvar[1] = 1; // Set flag
}`},"gps-check":{name:"GPS Fix Check",description:"Monitor GPS fix status",category:"Safety",code:`// Check GPS fix before allowing certain operations
const { flight, gvar } = inav;

if (flight.gpsNumSat < 6) {
  gvar[0] = 0; // No GPS - flag it
}

if (flight.gpsNumSat >= 6) {
  gvar[0] = 1; // Good GPS
}`},"multi-condition":{name:"Multiple Conditions",description:"Combine multiple flight parameters",category:"Advanced",code:`// Multiple conditions example
const { flight, override } = inav;

// Only boost VTX if far AND high
if (flight.homeDistance > 200 && flight.altitude > 50) {
  override.vtx.power = 4;
}

// Reduce throttle if battery low OR RSSI weak
if (flight.cellVoltage < 350 || flight.rssi < 40) {
  override.throttleScale = 60;
}`},"simple-counter":{name:"Simple Counter",description:"Count events using global variables",category:"Basic",code:`// Simple event counter
const { flight, gvar, edge } = inav;

// Initialize counter once on arm
edge(() => flight.armTimer > 1000, { duration: 0 }, () => {
  gvar[0] = 0;
});

// This runs continuously - increments every time altitude > 100
if (flight.altitude > 100) {
  gvar[0] = gvar[0] + 1;
}`},"edge-detection":{name:"Edge Detection",description:"Detect rising edge of a condition (executes once)",category:"Advanced",code:`// Detect when RSSI drops below threshold (once)
const { flight, gvar, edge } = inav;

