const { waypoint, gvar } = inav;

if (waypoint.distanceToHome < 10) {
  gvar[0] = 1; // Arrived at waypoint
}

if (waypoint.distanceToHome > 20) {
  gvar[0] = 0; // Not at waypoint
}`},"rc-controlled":{name:"RC Switch Control",description:"Use RC switch to control features",category:"RC Control",code:`// Use RC switch to control VTX power
